import type { LabCode } from './codes.ts';

export type Lab = { name: string; capacity: number };
export type LabTable = { [code: string]: Lab };

export const LAB_INFO: LabTable = {
  'BE-201': { name: 'Backend Lab 1', capacity: 40 },
  'BE-202': { name: 'Backend Lab 2', capacity: 40 },
  'AL-301': { name: 'AI Lab', capacity: 30 },
};

export function capacityOf(code: LabCode): number {
  return LAB_INFO[code]?.capacity ?? 0;
}

// LabFlow lab codes (given — do not edit).
export const LABS = ['BE-201', 'BE-202', 'AL-301'] as const;
export type LabCode = (typeof LABS)[number];

export function isLab(text: string): text is LabCode {
  return LABS.some((lab) => lab === text);
}

import { LAB_INFO } from '../src/labs.ts';
import { LABS } from '../src/codes.ts';

for (const code of LABS) {
  const seats: number = LAB_INFO[code].capacity;
  console.log(code, seats);
}

import { LAB_INFO } from '../src/labs.ts';
import type { LabTable } from '../src/labs.ts';

const ghost = LAB_INFO['BE-999']; // expect TS7053
const two: LabTable = { 'BE-201': { name: 'Backend Lab 1', capacity: 40 }, 'BE-202': { name: 'Backend Lab 2', capacity: 40 } }; // expect TS2741
declare const fromUrl: string;
const raw = LAB_INFO[fromUrl]; // expect TS7053
export { ghost, two, raw };

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { capacityOf } from '../src/labs.ts';

test('capacity', () => assert.deepEqual([capacityOf('BE-201'), capacityOf('AL-301')], [40, 30]));

