import type { LabCode } from './codes.ts';

export type Row = { lab: LabCode; seats: number; cancelled: boolean };

// Seats booked per lab today (cancelled rows do not count).
export function seatsByLab(rows: readonly Row[]): { [lab: string]: number } {
  const total: { [lab: string]: number } = {};
  for (const r of rows) {
    if (!r.cancelled) total[r.lab] = (total[r.lab] ?? 0) + r.seats;
  }
  return total;
}

// LabFlow lab codes (given — do not edit).
export const LABS = ['BE-201', 'BE-202', 'AL-301'] as const;
export type LabCode = (typeof LABS)[number];

export function isLab(text: string): text is LabCode {
  return LABS.some((lab) => lab === text);
}

import { seatsByLab } from '../src/count.ts';

const result = seatsByLab([{ lab: 'BE-201', seats: 30, cancelled: false }]);
const be202: number = result['BE-202'];
const percent: number = Math.round((be202 / 40) * 100);
console.log(percent);

import { seatsByLab } from '../src/count.ts';

const result = seatsByLab([]);
const ghost = result['BE-999']; // expect TS7053
const text: string = result['BE-201']; // expect TS2322
export { ghost, text };

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { seatsByLab } from '../src/count.ts';

test('every lab, zeros included', () => assert.deepEqual(
  seatsByLab([{ lab: 'BE-201', seats: 30, cancelled: false }, { lab: 'AL-301', seats: 25, cancelled: false }, { lab: 'BE-201', seats: 6, cancelled: false }]),
  { 'BE-201': 36, 'BE-202': 0, 'AL-301': 25 },
));
test('cancelled rows do not count', () => assert.deepEqual(seatsByLab([{ lab: 'AL-301', seats: 25, cancelled: true }]), { 'BE-201': 0, 'BE-202': 0, 'AL-301': 0 }));

