export type User = { readonly id: number; name: string };

export function indexById(users: readonly User[]): Record<number, User> {
  const byId: Record<number, User> = {};
  for (const u of users) byId[u.id] = u;
  return byId;
}

// "Always finds the user" — a promise the data cannot keep.
export function findUser(byId: Record<number, User>, id: number): User {
  return byId[id] as User;
}

export function nameOf(byId: Record<number, User>, id: number): string {
  return findUser(byId, id).name;
}

import { indexById, findUser } from '../src/users.ts';
import type { User } from '../src/users.ts';

const byId = indexById([{ id: 1, name: 'An' }]);
const maybe: User | undefined = findUser(byId, 2);
console.log(maybe?.name ?? 'nobody');

import { indexById, findUser } from '../src/users.ts';

const byId = indexById([{ id: 1, name: 'An' }]);
const name: string = findUser(byId, 2).name; // expect TS2532
export { name };

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { indexById, findUser, nameOf } from '../src/users.ts';

const byId = indexById([{ id: 1, name: 'Nguyen Van An' }, { id: 2, name: 'Tran Thi Binh' }]);
test('found', () => assert.equal(nameOf(byId, 2), 'Tran Thi Binh'));
test('a deleted user does not crash', () => assert.equal(nameOf(byId, 99), '(deleted user)'));
test('findUser misses with undefined', () => assert.equal(findUser(byId, 99), undefined));

